#[test]
fn unlinked_overlay_slot_is_scrubbed_before_reuse() {
    let bytes = index_bytes();
    let mut vfs: VirtualFs<'_, Reader, 2, 32, 4> =
        VirtualFs::new(Index::new(&bytes).unwrap(), Reader(*b"BASETOOL"));
    let w = vfs.open(b"/usr/scrub", O_WRITE | O_CREATE).unwrap();
    vfs.write(w, b"secret").unwrap();
    vfs.close(w).unwrap();
    let r = vfs.open(b"/usr/scrub", O_READ).unwrap();
    vfs.unlink(b"/usr/scrub").unwrap();
    let mut out = [0u8; 6];
    assert_eq!(vfs.read(r, &mut out), Ok(6));
    assert_eq!(&out, b"secret");
    vfs.close(r).unwrap();
    // the freed slot must be scrubbed: a fresh overlay starts empty
    let w2 = vfs.open(b"/usr/other", O_WRITE | O_CREATE | O_READ).unwrap();
    assert_eq!(vfs.read(w2, &mut out), Ok(0));
    vfs.write(w2, b"ab").unwrap();
    assert_eq!(vfs.read(w2, &mut out[..2]), Ok(0));
}

#[test]
fn duplicate_retains_pipe_ends_and_survives_source_close() {
    let mut pipes: PipeSpace<2, 8, 2> = PipeSpace::new();
    let id = pipes.create_pipe(1, 0, 1, false).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    // duplicating both ends raises the count to four
    pipes.duplicate(1, 0, 2, false).unwrap();
    pipes.duplicate(1, 1, 3, false).unwrap();
    assert_eq!(pipes.pipe_ends(id), 4);
    // closing the originals leaves the pipe alive through the copies
    pipes.close(1, 0).unwrap();
    pipes.close(1, 1).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    assert_eq!(pipes.active_pipes(), 1);
    // only the last copy frees it
    pipes.close(1, 2).unwrap();
    assert_eq!(pipes.pipe_ends(id), 1);
    pipes.close(1, 3).unwrap();
    assert_eq!(pipes.pipe_ends(id), 0);
    assert_eq!(pipes.active_pipes(), 0);
}

