#[test]
fn create_only_filesystem_grants_derive_write() {
    let recipe = VALID.replace(
        "[storage]",
        "[contract.filesystem]\ndefault = \"deny\"\nread = []\nwrite = []\ncreate = [\"/tmp\"]\ndeny = []\n[contract.kernel]\ndefault = \"deny\"\nproc_read = [\"/\"]\nproc_write = []\nsys_read = [\"/\"]\nsys_write = []\n[storage]",
    );
    let c = InstanceConfig::parse(recipe.as_bytes()).unwrap();
    assert!(c.filesystem_write.as_slice().is_empty());
    assert_eq!(c.filesystem_create.as_slice().len(), 1);
    // create-only policy must still mediate writes (create implies write path)
    assert!(c.contract_write.as_slice().iter().any(|t| t.as_bytes() == b"filesystem.**"));
    // read stays empty: no read grant without read policy
    assert!(!c.contract_read.as_slice().iter().any(|t| t.as_bytes() == b"filesystem.**"));
}

#[test]
fn validate_pins_identifier_and_hostname_edges() {
    let src = VALID.replace("[resources]", "[identity]\nhostname = \"host.example\"\n\n[resources]");
    let mut c = InstanceConfig::parse(src.as_bytes()).unwrap();
    assert_eq!(c.hostname.as_bytes(), b"host.example");
    assert!(c.validate().is_ok());
    // id edges: empty and space rejected, alnum accepted
    c.id = Text::from_bytes(b"").unwrap();
    assert!(c.validate().is_err());
    c.id = Text::from_bytes(b"bad id").unwrap();
    assert!(c.validate().is_err());
    c.id = Text::from_bytes(b"demo").unwrap();
    assert!(c.validate().is_ok());
    // hostname edges are validated independently of id
    c.hostname = Text::from_bytes(b"bad host").unwrap();
    assert!(c.validate().is_err());
    c.hostname = Text::from_bytes(b"").unwrap();
    assert!(c.validate().is_err());
    c.hostname = Text::from_bytes(b"host-2.example").unwrap();
    assert!(c.validate().is_ok());
}

#[test]
fn override_instance_id_and_reject_unknown() {
    let mut c = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    c.apply_override(b"instance.id", b"\"other\"").unwrap();
    assert_eq!(c.id.as_bytes(), b"other");
    // unknown keys fail closed without partial mutation
    assert!(c.apply_override(b"instance.nope", b"\"x\"").is_err());
    // unquoted value is a syntax error, not a silent accept
    assert!(c.apply_override(b"instance.id", b"bare").is_err());
    assert_eq!(c.id.as_bytes(), b"other");
}

#[test]
fn memory_override_enforces_exact_bounds() {
    let mut c = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    c.apply_override(b"resources.memory_mib", b"256").unwrap();
    assert_eq!(c.memory_mib, 256);
    // exact lower bound accepted, one below rejected without partial mutation
    c.apply_override(b"resources.memory_mib", b"16").unwrap();
    assert_eq!(c.memory_mib, 16);
    assert!(c.apply_override(b"resources.memory_mib", b"15").is_err());
    assert_eq!(c.memory_mib, 16);
    // non-numeric values fail closed
    assert!(c.apply_override(b"resources.memory_mib", b"\"256\"").is_err());
    assert_eq!(c.memory_mib, 16);
}

#[test]
fn pipe_ends_reports_zero_for_invalid_and_dead_pipes() {
    let mut pipes: PipeSpace<2, 8, 2> = PipeSpace::new();
    // pipe 0 is always invalid
    assert_eq!(pipes.pipe_ends(0), 0);
    // out-of-range pipe ids: far beyond and exactly one past the table
    assert_eq!(pipes.pipe_ends(99), 0);
    assert_eq!(pipes.pipe_ends(3), 0);
    // create a pipe, verify ends=2
    let id = pipes.create_pipe(1, 6, 7, false).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    // close both ends -> pipe freed, ends report 0
    pipes.close(1, 6).unwrap();
    pipes.close(1, 7).unwrap();
    assert_eq!(pipes.pipe_ends(id), 0);
    // re-create at same slot, verify fresh count
    let id2 = pipes.create_pipe(1, 3, 4, false).unwrap();
    assert_eq!(pipes.pipe_ends(id2), 2);
}

